def generate():
    for p in PROBLEMS_DATA:
        tier_dir = os.path.join(PROBLEMS_DIR, p["tier"], p["id"])
        hidden_dir = os.path.join(tier_dir, "hidden_tests")
        os.makedirs(hidden_dir, exist_ok=True)
        
        # Save problem.json
        pj_path = os.path.join(tier_dir, "problem.json")
        with open(pj_path, "w", encoding="utf-8") as f:
            json.dump(p, f, indent=2)
            
        # Save hidden tests
        for i, test in enumerate(p.get("hidden_tests", []), start=1):
            tf_path = os.path.join(hidden_dir, f"test{i}.txt")
            with open(tf_path, "w", encoding="utf-8") as f:
                f.write(f"INPUT:\n{test['input']}\nEXPECTED:\n{test['output']}\n")

